 edit=f'<a href="downloads/{bundle}.zip" download>SVGs editáveis ↓</a>' if paired else f'<a href="downloads/{s}.svg" download>SVG editável ↓</a>'
 if s=='papel-timbrado':edit+='<a href="downloads/papel-timbrado.docx" download>Word editável ↓</a>'
